def transform(grid):
    """Tile each 3x5 section's non-background pattern across the 3 columns and 3 row bands."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Color 4 forms row/column separators; replicate each pattern block's colors
    # into matching positions across the separated regions.
    row_bands = []
    start = 0
    for r in range(h):
        if all(v == 4 for v in grid[r]):
            if start < r:
                row_bands.append((start, r))
            start = r + 1
    if start < h:
        row_bands.append((start, h))
    col_bands = []
    start = 0
    for c in range(w):
        if all(grid[r][c] == 4 for r in range(h)):
            if start < c:
                col_bands.append((start, c))
            start = c + 1
    if start < w:
        col_bands.append((start, w))
    # Use first band as the repeated motif, filling corresponding positions
    # in all bands while preserving separators and background cells.
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            for rr in range(r1-r0):
                for cc in range(c1-c0):
                    source = grid[row_bands[0][0] + rr][col_bands[0][0] + cc]
                    if source != 1:
                        out[r0+rr][c0+cc] = source
    return out
